        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://pt.wikiquote.org/wiki/Guimarães_Rosa", Text = "O homem nasceu para aprender, aprender tanto quanto a vida lhe permita.", Author = "Guimarães Rosa" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Guimarães_Rosa", Text = "Saudade é ser, depois de ter.", Author = "Guimarães Rosa" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Guimarães_Rosa", Text = "O amor é sede depois de se ter bem bebido.", Author = "Guimarães Rosa" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Guimarães_Rosa", Text = "Esperar é reconhecer-se incompleto.", Author = "Guimarães Rosa" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Guimarães_Rosa", Text = "Infelicidade é questão de prefixo.", Author = "Guimarães Rosa" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Guimarães_Rosa", Text = "Eu quase que nada não sei. Mas desconfio de muita coisa.", Author = "Guimarães Rosa" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Guimarães_Rosa", Text = "A colheita é comum, mas o capinar é sozinho.", Author = "Guimarães Rosa" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Guimarães_Rosa", Text = "A lembrança da vida da gente se guarda em trechos diversos, cada um com seu signo e sentimentos, uns com os outros acho que nem se mistura.", Author = "Guimarães Rosa" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Guimarães_Rosa", Text = "Mire veja: sabe por que é que eu não purgo remorso? Acho que o que não deixa é a minha boa memória. A luzinha dos santos-arrependidos se acende é no escuro.", Author = "Guimarães Rosa" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Guimarães_Rosa", Text = "Como é que posso com este mundo? A vida é ingrata no macio de si; mas transtraz a esperança mesmo do macio do meio do fel do desespero. Ao que, este mundo é muito misturado...", Author = "Guimarães Rosa" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Guimarães_Rosa", Text = "O que tivesse de ser, somente sendo. Não era nem o Hermógenes, era um estado de lei, nem dele não era, eu cumpria, todos cumpriam.", Author = "Guimarães Rosa" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Guimarães_Rosa", Text = "Ao que naquele tempo, eu não sabia pensar com poder. Aprendendo eu estava? Não sabia pensar com poder - por isso matava.", Author = "Guimarães Rosa" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Guimarães_Rosa", Text = "O correr da vida embrulha tudo, a vida é assim: esquenta e esfria, aperta e daí afrouxa, sossega e depois desinquieta. O que ela quer da gente é coragem.", Author = "Guimarães Rosa" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Guimarães_Rosa", Text = "As pessoas não morrem, ficam encantadas.", Author = "Guimarães Rosa" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Guimarães_Rosa", Text = "Passarinho que se debruça - o voo já está pronto!", Author = "Guimarães Rosa" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Guimarães_Rosa", Text = "Qualquer amor é um pouquinho de saúde, um descanso na loucura.", Author = "Guimarães Rosa" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Guimarães_Rosa", Text = "Pão ou pães é questão de opiniães.", Author = "Guimarães Rosa" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Guimarães_Rosa", Text = "Porque a cabeça da gente é uma só, e as coisas que há e que estão para haver são demais de muitas, muito maiores diferentes, e a gente tem de necessitar de aumentar a cabeça, para o total.", Author = "Guimarães Rosa" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Guimarães_Rosa", Text = "Mestre não é quem sempre ensina, mas quem de repente aprende.", Author = "Guimarães Rosa" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Guimarães_Rosa", Text = "Que Deus existe, sim, devagarinho, depressa. Ele existe - mas quase só por intermédio da ação das pessoas: de bons e maus. Coisas imensas no mundo. O grande-sertão é a forte arma. Deus é um gatilho?", Author = "Guimarães Rosa" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Guimarães_Rosa", Text = "Vida\" é noção que a gente completa seguida assim, mas só por lei duma idéia falsa. Cada dia é um dia.", Author = "Guimarães Rosa" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Guimarães_Rosa", Text = "O senhor não esteve lá. O senhor não escutou, em cada anoitecer, a lugúmem do canto da mãe-da-lua. O senhor não pode estabelecer em sua ideia a minha tristeza quinhoã. Até os pássaro, consoante os lugares, vão sendo muito diferentes. Ou são os tempos, travessia da gente?", Author = "Guimarães Rosa" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Guimarães_Rosa", Text = "Vivendo, se aprende; mas o que se aprende, mais, é só a fazer outras maiores perguntas.", Author = "Guimarães Rosa" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Guimarães_Rosa", Text = "Viver é negócio muito perigoso.", Author = "Guimarães Rosa" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Guimarães_Rosa", Text = "Raiva tampa o espaço do mêdo, assim como do mêdo raiva vem.", Author = "Guimarães Rosa" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Guimarães_Rosa", Text = "Conto o que fui e vi, no levantar do dia. Auroras.", Author = "Guimarães Rosa" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Guimarães_Rosa", Text = "Miguilim, Miguilim, vou ensinar o que agorinha eu sei, demais: é que a gente pode ficar sempre alegre, alegre, mesmo com toda coisa ruim que acontece acontecendo. A gente deve de poder ficar então mais alegre, mais alegre, por dentro!", Author = "Guimarães Rosa" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Guimarães_Rosa", Text = "Dito, eu às vezes tenho uma saudade de uma coisa que eu não sei o que é, nem de donde, me afrontando...", Author = "Guimarães Rosa" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Guimarães_Rosa", Text = "E Miguilim mesmo se achava diferente de todos. Ao vago, dava a mesma idéia de uma vez, em que, muito pequeno, tinha dormido de dia, fora de seu costume - quando acordou, sentiu o existir do mundo em hora estranha, e perguntou assustado: — 'Uai, Mãe, hoje já é amanhã?!'", Author = "Guimarães Rosa" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Guimarães_Rosa", Text = "Um dia, tempos, Tio Terêz o levara à beira da mata, ia tirar taquaras. A gente fazia um feixe e carregava. '— Miguilim, este feixinho está muito pesado para você?'. '— Tio Terêz, está não. Se a gente puder ir devagarinho como precisa, e ninguém não gritar com a gente para ir depressa demais, então eu acho que nunca que é pesado...'", Author = "Guimarães Rosa" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Guimarães_Rosa", Text = "Sofri o grave frio dos mêdo, adoeci. Sei que ninguém soube mais dele. Sou homem, depois desse falimento? Sou o que não foi, o que vai ficar calado. Sei que agora é tarde, e temo abreviar com a vida, nos rasos do mundo. Mas, então, ao menos, que, no artigo da morte, peguem em mim, e me depositem também numa canoinha de nada, nessa água que não pára, de longas beiras: e, eu, rio abaixo, rio a fora, rio a dentro — o rio.", Author = "Guimarães Rosa" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Guimarães_Rosa", Text = "Cada palavra é, segundo a sua essência, um poema.", Author = "Guimarães Rosa" },
